<?php $money=static fn(int$v):string=>($v<0?'- ':'').'R$ '.number_format(abs($v)/100,2,',','.'); ?>
<header class="panel-page-heading"><div><span>Programa de afiliados</span><h1>Olá, <?= e($affiliate['nome']) ?></h1><p>Acompanhe suas indicações e seus resultados financeiros.</p></div><span class="status-pill affiliate-status-<?= e($affiliate['status']) ?>"><?= e(ucfirst($affiliate['status'])) ?></span></header>
