<section class="panel-card affiliate-share-card">
    <div class="panel-card-heading"><div><h2>Divulgação</h2><p>Compartilhe seu código ou o link direto de cadastro.</p></div></div>
    <div class="affiliate-share-grid">
        <div class="affiliate-share-item"><label for="affiliate-code">Seu código de afiliado</label><div class="affiliate-link-row"><input id="affiliate-code" value="<?= e($affiliate['codigo']) ?>" readonly aria-readonly="true"><button class="btn btn-outline" type="button" data-copy-target="affiliate-code">Copiar código</button></div></div>
        <div class="affiliate-share-item"><label for="affiliate-referral-link">Seu link de divulgação</label><div class="affiliate-link-row"><textarea id="affiliate-referral-link" rows="2" readonly aria-readonly="true"><?= e($referralLink) ?></textarea><button class="btn btn-primary" type="button" data-copy-target="affiliate-referral-link">Copiar link</button></div></div>
    </div>
    <p class="affiliate-copy-feedback" data-copy-feedback aria-live="polite"></p>
</section>
<script>document.querySelectorAll('[data-copy-target]').forEach(button=>button.addEventListener('click',async()=>{const input=document.getElementById(button.dataset.copyTarget),feedback=document.querySelector('[data-copy-feedback]');try{await navigator.clipboard.writeText(input.value)}catch(_){input.select();document.execCommand('copy')}feedback.textContent=button.dataset.copyTarget==='affiliate-code'?'Código copiado.':'Link copiado.';}));</script>
